package main

import (
	"fmt"
	"math"
)

type TreeNode struct {
	Val         int
	Left, Right *TreeNode
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func height(n *TreeNode) int {
	if n == nil {
		return 0
	}
	return 1 + maxInt(height(n.Left), height(n.Right))
}

func countLeaves(n *TreeNode) int {
	if n == nil {
		return 0
	}
	if n.Left == nil && n.Right == nil {
		return 1
	}
	return countLeaves(n.Left) + countLeaves(n.Right)
}

func maxValue(n *TreeNode) int {
	if n == nil {
		return math.MinInt64 // any real value beats it
	}
	return maxInt(n.Val, maxInt(maxValue(n.Left), maxValue(n.Right)))
}

func countEven(n *TreeNode) int {
	if n == nil {
		return 0
	}
	count := countEven(n.Left) + countEven(n.Right)
	if n.Val%2 == 0 {
		count++
	}
	return count
}

