	root := &TreeNode{
		Val:   -7,
		Left:  &TreeNode{Val: -12, Left: &TreeNode{Val: -3}, Right: &TreeNode{Val: -8, Left: &TreeNode{Val: -6}}},
		Right: &TreeNode{Val: -4, Right: &TreeNode{Val: -15}},
	}
	fmt.Println("height:", height(root))
	fmt.Println("leaves:", countLeaves(root))
	fmt.Println("max:", maxValue(root))
	fmt.Println("evens:", countEven(root))
