steps.body:
A **binary search tree** (BST) keeps one rule at every node: smaller values go in the left subtree and larger values in the right. To insert, walk down and hang a new node on the nil spot you reach.

```go harness
package main

import "fmt"

type TreeNode struct {
	Val         int
	Left, Right *TreeNode
}

{{code}}

func inorder(n *TreeNode, out *[]int) {
	if n != nil {
		inorder(n.Left, out)
		*out = append(*out, n.Val)
		inorder(n.Right, out)
	}
}

func main() {
	var root *TreeNode
	for _, v := range []int{5, 3, 8, 1, 4, 3} {
		root = insert(root, v)
	}
	var sorted []int
	inorder(root, &sorted)
	fmt.Println("root:", root.Val, "inorder:", sorted)
}
```

```go
func insert(n *TreeNode, v int) *TreeNode {
	if n == nil {
		return &TreeNode{Val: v}
	}
	if v < n.Val {
		n.Left = insert(n.Left, v)
	} else if v > n.Val {
		n.Right = insert(n.Right, v)
	}
	return n
}
```

`insert` returns the root because inserting into an empty tree creates one, so always write `root = insert(root, v)`. A value equal to `n.Val` matches neither branch, so a repeat is ignored.

Search needs no recursion: start at the root and step left or right until you reach the value or nil. Each step skips a whole subtree, so a balanced tree needs about log n steps. Sorted input builds a one-sided chain, and then search is as slow as a list.

Three facts follow from the rule:

- an inorder traversal visits the values in sorted order
- the minimum is the leftmost node: from a non-nil root, follow `Left` until it is nil
- the maximum is the rightmost node: follow `Right` until it is nil

example.code:
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type TreeNode struct {
	Val         int
	Left, Right *TreeNode
}

func insert(n *TreeNode, v int) *TreeNode {
	if n == nil {
		return &TreeNode{Val: v}
	}
	if v < n.Val {
		n.Left = insert(n.Left, v)
	} else if v > n.Val {
		n.Right = insert(n.Right, v)
	}
	return n // v == n.Val: already in the tree, so change nothing
}

func inorder(n *TreeNode, out *[]int) {
	if n != nil {
		inorder(n.Left, out)
		*out = append(*out, n.Val)
		inorder(n.Right, out)
	}
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var root *TreeNode
	var queries, sorted []int
	for i := 0; i < 2 && scanner.Scan(); i++ {
		for _, f := range strings.Fields(scanner.Text()) {
			v, err := strconv.Atoi(f)
			if err != nil {
				fmt.Println(err)
				return
			}
			if i == 0 {
				root = insert(root, v) // line 1: values
			} else {
				queries = append(queries, v) // line 2: queries
			}
		}
	}
	inorder(root, &sorted)
	fmt.Println("inorder:", sorted)
	lo, hi := root, root
	for lo.Left != nil {
		lo = lo.Left
	}
	for hi.Right != nil {
		hi = hi.Right
	}
	fmt.Println("min:", lo.Val, "max:", hi.Val)
	for _, q := range queries {
		n := root
		for n != nil && n.Val != q {
			if q < n.Val {
				n = n.Left
			} else {
				n = n.Right
			}
		}
		if n != nil {
			fmt.Println(q, "found")
		} else {
			fmt.Println(q, "missing")
		}
	}
}

