Recursion goes deep before it goes wide. To visit a tree **level by level**, run the BFS from the BFS lesson with a queue of `*TreeNode`: take a node off the front, then add its children to the back. Skip nil children, so the queue only ever holds real nodes.

```go harness
package main

import "fmt"

type TreeNode struct {
	Val         int
	Left, Right *TreeNode
}

func main() {
	root := &TreeNode{
		Val:   1,
		Left:  &TreeNode{Val: 2, Left: &TreeNode{Val: 4}, Right: &TreeNode{Val: 5}},
		Right: &TreeNode{Val: 3, Left: &TreeNode{Val: 6}, Right: &TreeNode{Val: 7}},
	}
	{{code}}
	fmt.Println("queue is empty:", len(queue) == 0)
}
```

```go
queue := []*TreeNode{root}
for len(queue) > 0 {
	n := queue[0]
	queue = queue[1:]
	if n.Left != nil {
		queue = append(queue, n.Left)
	}
	if n.Right != nil {
		queue = append(queue, n.Right)
	}
}
```

To know where one level ends, process the queue in rounds, as in the BFS lesson: save `size := len(queue)` at the start of each round and take exactly that many nodes. The children added during the round belong to the next level, and they wait behind the current ones.

Start only when the root is not nil, because an empty tree has no levels and `[]*TreeNode{nil}` would crash on `n.Val`. The queue stores pointers, so adding a node copies 8 bytes, never the node itself, and `queue[1:]` copies no elements, just as in the BFS lesson.

example.code:
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type TreeNode struct {
	Val         int
	Left, Right *TreeNode
}

func insert(n *TreeNode, v int) *TreeNode {
	if n == nil {
		return &TreeNode{Val: v}
	}
	if v < n.Val {
		n.Left = insert(n.Left, v)
	} else if v > n.Val {
		n.Right = insert(n.Right, v)
	}
	return n
}

func main() {
	var root *TreeNode
	for {
		var v int
		if _, err := fmt.Scan(&v); err != nil {
			break
		}
		root = insert(root, v)
	}
	if root == nil {
		return // empty input: no levels to print
	}
	queue := []*TreeNode{root}
	for len(queue) > 0 {
		size := len(queue) // the nodes of exactly one level
		var level []string
		for i := 0; i < size; i++ {
			n := queue[0]
			queue = queue[1:]
			level = append(level, strconv.Itoa(n.Val))
			if n.Left != nil {
				queue = append(queue, n.Left)
			}
			if n.Right != nil {
				queue = append(queue, n.Right)
			}
		}
		fmt.Println(strings.Join(level, " "))
	}
}

