		root = insert(root, v)
	}
	if root == nil {
		return
	}
	queue := []*TreeNode{root}
	for depth := 1; len(queue) > 0; depth++ {
		size, sum := len(queue), 0
		for i := 0; i < size; i++ {
			n := queue[0]
